for file,spans in [('COMBAT_ACTION_PLAYTEST.md',[(150,164)]),('GAMEPLAY_LOOP_CANON.md',[(691,714)])]:
 lines=(R/'docs/mechanics'/file).read_text(encoding='utf-8').splitlines(); packet+='\n'+file+'\n'+ '\n'.join(f'{i+1}: {lines[i]}' for lo,hi in spans for i in range(lo-1,min(hi,len(lines))))+'\n'
packet+='\nThe bounded current gameplay-loop source review found Opening2,400hours/Horn1,200 and formal extraction route/cargo/Pressure procedures, but no explicit blanket teleport or planar prohibition. Preserve that distinction; destination travel may avoid a route segment while actual elapsed time, safe arrival, cargo, claims, contamination and settlement remain real. General mounts/3D templates are explicitly further-review items in combat, so provide self-contained spell-specific riding procedure and do not claim all mounted combat closed.\n'
p=A/'CODEX_CONJURATION_RANK3_SOURCE_CONFERENCE.md';assert not p.exists();p.write_text(packet,encoding='utf-8')
d={'status':'prepared for source conference','ids':[s['id'] for s in rows],'count':7,'sourcePlacements':7,'sourceCoreBlocks':7,'packetPath':str(p),'packetSha256':hashlib.sha256(p.read_bytes()).hexdigest(),'operationalBefore':152,'unfinishedBefore':696}
(A/'CONJURATION_RANK3_CONFERENCE_SUBMISSION.json').write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8');print(json.dumps({'count':7,'packetCharacters':len(packet),'packetSha256':d['packetSha256']},indent=2))
